{
  "name": "@vymalo/opencode-otel",
  "version": "0.20.2",
  "description": "OpenTelemetry plugin for OpenCode: exports developer interactions as OTLP traces, metrics and logs — real USD cost, all five token types (including cache read/write and reasoning), tool results, permission decisions and API errors. Configurable from opencode.json or standard OTEL_* environment variables.",
  "license": "MIT",
  "author": "vymalo contributors",
  "homepage": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit.git",
    "directory": "packages/opencode-otel"
  },
  "bugs": {
    "url": "https://github.com/ADORSYS-GIS/lightbridge-opencode-toolbeit/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opentelemetry",
    "otel",
    "otlp",
    "observability",
    "telemetry",
    "tracing",
    "metrics",
    "cost-tracking",
    "gen-ai",
    "llm"
  ],
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./lib": {
      "types": "./dist/lib.d.ts",
      "import": "./dist/lib.js"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.6",
    "@opentelemetry/api": "^1.9.1",
    "@opentelemetry/core": "^2.11.0",
    "@vymalo/opencode-core-otel": "0.20.2"
  },
  "devDependencies": {
    "@opentelemetry/sdk-logs": "^0.222.0",
    "@opentelemetry/sdk-trace": "^2.11.0",
    "effect": "4.1.0",
    "vite": "^8.3.0",
    "vitest": "^5.0.1"
  },
  "peerDependencies": {
    "effect": "^4.0.0"
  },
  "scripts": {
    "build": "node ../../scripts/build-package.mjs",
    "lint": "biome lint .",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "coverage": "vitest run --coverage",
    "format": "biome format --write .",
    "format:check": "biome format ."
  }
}
